WITH scored AS (SELECT id, country, city, rating, ROW_NUMBER() OVER w_running event_seq, LAG(rating, 2) OVER (ORDER BY rating, id) prev_rating, RANK() OVER (PARTITION BY country ORDER BY rating DESC NULLS FIRST) rating_rank, COUNT(rating) OVER (PARTITION BY country, city) country_count_rating FROM suppliers WHERE country <> 'JP' WINDOW w_running AS (PARTITION BY city ORDER BY rating, id)) SELECT id, country, city, rating, event_seq, rating_rank, country_count_rating FROM scored ORDER BY event_seq DESC;
